import { sprintf }				from 'sprintf-js';
import { AccCatId, type AccConfig, type SrvCharacteristic, type GeneratorContext, type GeneratorResult } from '../types';
import { constChar, objName, onlyAck, sortBy } from '../helpers';


// ~~~~~~~~
// ROLE_MAP
// ~~~~~~~~
// accessory generated by create_by_role() for a state role
const ROLE_MAP: Record<string, { category: string, type: string, chars: (id: string, name: string) => SrvCharacteristic[] }> = {
	'sensor.contact':	{ category: AccCatId.Sensor,				type: 'ContactSensor',		chars: (id, name) => [ constChar('Name', name), onlyAck('ContactSensorState', id) ] },
	'sensor.motion':	{ category: AccCatId.Sensor,				type: 'MotionSensor',		chars: (id, name) => [ constChar('Name', name), onlyAck('MotionDetected', id) ] },
	'sensor.occupancy':	{ category: AccCatId.Sensor,				type: 'OccupancySensor',	chars: (id, name) => [ constChar('Name', name), onlyAck('OccupancyDetected', id) ] },
	'sensor.leak':		{ category: AccCatId.Sensor,				type: 'LeakSensor',			chars: (id, name) => [ constChar('Name', name), onlyAck('LeakDetected', id) ] },
	'switch':			{ category: AccCatId.Switch,				type: 'Switch',				chars: (id, name) => [ constChar('Name', name), onlyAck('On', id) ] },
	'switch.light':		{ category: AccCatId.Lightbulb,				type: 'Lightbulb',			chars: (id, name) => [ constChar('Name', name), onlyAck('On', id) ] },
	'switch.fan':		{ category: AccCatId.Fan,					type: 'Fan',				chars: (id, name) => [ constChar('Name', name), onlyAck('On', id) ] },
	'switch.lock.door':	{ category: AccCatId.Door_lock,				type: 'LockMechanism',		chars: (id, name) => [
		constChar('Name', name),
		onlyAck('LockTargetState',  id,           { 'conversionFunction': 'invert' }),
		onlyAck('LockCurrentState', id+'_status', { 'conversionFunction': 'invert' }),
	] },
	'switch.garage':	{ category: AccCatId.Garage_door_opener,	type: 'GarageDoorOpener',	chars: (id, name) => [
		constChar('Name', name),
		onlyAck('TargetDoorState',  id,           { 'conversionFunction': 'invert' }),
		onlyAck('CurrentDoorState', id+'_status', { 'conversionFunction': 'invert' }),
		constChar('ObstructionDetected', false),
	] },
};


export async function createByRole({ adapter, srcInstId }: GeneratorContext): Promise<GeneratorResult> {
	const accConfigs: AccConfig[] = [];
	const historyIds: string[] = [];

	const pinObjs = await adapter.getForeignObjectsAsync(`${srcInstId}.*`, 'state');
	for (const pinObj of Object.values(pinObjs).sort(sortBy('_id'))) {
		const objId		= pinObj._id;									//   '0_userdata.0.pin.tür_tag'
		const idPath	= pinObj._id.split('.');						// [ '0_userdata', '0', 'pin', 'tür_tag' ]
		const objRole	= pinObj.common.role;							// 'value.temperature'
		const name		= objName(pinObj);								// 'Haustür'

		// yahka device config
		const accConfig: AccConfig = {
			'category':			'',
			'name':				objId,									// NOTE: yahka adapter uses 'name' to build homekit UUID!
			'manufacturer':		idPath.slice(0,2).join('.'),			// visible within iOS home app
			'serial':			idPath.slice(2  ).join('.'),			// visible within iOS home app
			'model':			name,									// visible within iOS home app
			'services':			[],										// default
			'groupString':		idPath.slice(0,2).join('.')				// used by adapter only
		};

		// services by role
		const mapped = Object.hasOwn(ROLE_MAP, objRole) ? ROLE_MAP[objRole] : undefined;
		if (mapped) {
			accConfig.category = mapped.category;
			accConfig.services = [
				{ 'type': mapped.type, 'subType': '', 'name': name, 'characteristics': mapped.chars(objId, name) }
			];
		}

		// add accConfig
		if (accConfig.services.length > 0) {
			accConfigs.push(accConfig);
			for (const accService of accConfig.services) {
				adapter.log.debug(sprintf('%-30s %-20s %-50s %s', 'create_by_role()', accService.type, accConfig.name, accService.name));
			}
		}
	}

	return { devices: accConfigs, invalid: [], historyIds };

}
